mapper.select:
select id, is_deleted, nezha_tenant_code, name, description, status, agent_unique_id, public_key, auth_policy, owner_id, agent_type, create_at, create_by, create_name, update_at, update_by, update_name from agent_identity where is_deleted = 0
and name like concat('%', #{name,jdbcType=VARCHAR}, '%')
and status = #{status,jdbcType=VARCHAR}
and agent_type = #{agentType,jdbcType=VARCHAR}
and owner_id = #{ownerId,jdbcType=VARCHAR}
order by id desc
